#include <algorithm>
#include <numeric>
#include <vector>

int main() {
    std::vector<int> scores{72, 91, 55, 80, 64, 98};

    std::sort(scores.begin(), scores.end());               // 55 64 72 80 91 98.
    auto it = std::lower_bound(scores.begin(), scores.end(), 80);   // needs sorted: first >= 80.
    auto passing = std::distance(it, scores.end());         // 3 scores >= 80.

    int total = std::accumulate(scores.begin(), scores.end(), 0);   // 460.
    auto high = std::count_if(scores.begin(), scores.end(),
                              [](int s) { return s >= 90; });      // 2.

    auto new_end = std::remove_if(scores.begin(), scores.end(),
                                  [](int s) { return s < 60; });    // moves keepers forward.
    scores.erase(new_end, scores.end());                    // actually shrinks: 5 left.
    // C++20 one-liner: std::erase_if(scores, [](int s) { return s < 60; });
    (void)passing; (void)total; (void)high;
}
